def transform(grid):
    h, w = len(grid), len(grid[0])

    # Record the colors of the marked anti-diagonals, indexed by row+column.
    clues = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color:
                clues.setdefault(r + c, set()).add(color)

    # Find the smallest period that places repeated colors at matching phases
    # without making two different colors occupy the same phase.
    max_period = max(h, w) * 2
    period = max_period
    for p in range(1, max_period + 1):
        phases = {}
        valid = True
        for s, colors in clues.items():
            for color in colors:
                phase = s % p
                if phase in phases and phases[phase] != color:
                    valid = False
                    break
                phases[phase] = color
            if not valid:
                break
        if valid:
            period = p
            break

    phases = {}
    for s, colors in clues.items():
        for color in colors:
            phases[s % period] = color

    # Complete any unmarked phases by cycling the known colors in phase order.
    known = [phases[i] for i in sorted(phases)]
    if not known:
        return [row[:] for row in grid]
    pattern = [phases.get(i, known[i % len(known)]) for i in range(period)]

    return [[pattern[(r + c) % period] for c in range(w)] for r in range(h)]
